<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Ball Physics</title>
<style>
  body {
    margin: 0;
    padding: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background-color: #1a1a1a;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  }

  .container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 15px;
  }

  canvas#sim {
    background-color: #000;
    border-radius: 8px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6);
    /* At least 400x400 CSS pixels */
    width: 500px !important; 
    height: 500px !important;
    border: 1px solid #333;
    cursor: crosshair;
  }

  .controls {
    display: flex;
    gap: 10px;
  }

  button {
    padding: 10px 20px;
    font-size: 16px;
    border: none;
    border-radius: 4px;
    background-color: #3d5afe; 
    color: white;
    cursor: pointer;
    transition: transform 0.1s ease, opacity 0.2s;
    box-shadow: 0 2px 5px rgba(0,0,0,0.3);
  }

  button:hover { background-color: #4f6ff8; }
  button:active { transform: scale(0.95); opacity: 0.8; }

  /* Specific buttons */
  #drop { background-color: #2bbd7e; color:white;} 
  #play   { background-color: #ffc107; color:black; font-weight:bold;} 
  #clear  { background-color: #ef3c46; color:white;}

</style>
</head>
<body>

<div class="container">
    <canvas id="sim" width="500" height="500"></canvas>
    <div class="controls">
        <button id="drop">Drop Ball</button>
        <button id="play">Play/Pause</button>
        <button id="clear">Clear All</button>
    </div>
</div>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');

  // Physics constants
  const GRAVITY = 0.5; 
  const RESTITUTION = 0.78; 
  const FRICTION = 1.0; 

  let balls = [];

  // Dimensions (in pixels) for physics logic - internal canvas resolution
  const W = parseInt(canvas.width); 
  const H = parseInt(canvas.height);

  function drawBall(ball) {
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);

    // Fill based on index or random? Let's use consistent colors.
    const hue = (Math.floor(Math.random() * 360));
    ctx.fillStyle = `hsl(${hue}, 70%, 60%)`; 
    ctx.fill();

    // Stroke for contrast against dark background
    ctx.lineWidth = 2;
    ctx.strokeStyle = 'white';
    ctx.stroke();

    // Add a subtle highlight to make it look spherical (satisfying)
    ctx.beginPath();
    ctx.arc(ball.x - ball.r*0.3, ball.y - ball.r*0.3, ball.r/3, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.4)';
    ctx.fill();
  }

  // The required API implementation
  window.sim = {
    w: W, 
    h: H,

    balls() { return balls.slice(); },

    addBall(x, y, vx=0, vy=0, r) {
        if (r === undefined) r = Math.max(15, Math.floor(Math.random() * 20 + 10)); 
        // Ensure spawn inside bounds initially
        const safeX = Math.min(Math.max(r, x), W - r);
        const safeY = Math.min(Math.max(r, y), H - r);

        balls.push({ x: safeX, y: safeY, vx, vy, r });
    },

    clear() {
      balls = [];
      ctx.clearRect(0, 0, W, H); // Clear canvas immediately on command
    },

    step(dt=1) {
        // Advance the simulation one step (and redraw)

        // Clear background for this frame
        ctx.clearRect(0, 0, W, H);

        balls.forEach(ball => {
            ball.vy += GRAVITY * dt;

            // Air friction to settle things down eventually
            ball.vx *= FRICTION; 
            ball.vy *= FRICTION;

            ball.x += ball.vx * dt;
            ball.y += ball.vy * dt;

            // Floor Collision (Bottom)
            if (ball.y + ball.r > H) {
                ball.y = H - ball.r; // Clamp inside
                ball.vy *= -RESTITUTION; 
            } else if (ball.y - ball.r < 0) {
                ball.y = ball.r;     // Ceiling
                ball.vy *= -RESTITUTION;
            }

            // Right Wall Collision
            if (ball.x + ball.r > W) {
                ball.x = W - ball.r; 
                ball.vx *= -RESTITUTION;
            } else if (ball.x - ball.r < 0) {
                ball.x = ball.r;     // Left Wall
                ball.vx *= -RESTITUTION;
            }

            drawBall(ball);
        });
    },

    get isRunning() { return running; } 
  };

  // Animation loop (not part of the API, but powers 'play' button and general interaction)
  let running = true;
  let requestAnimFrameId = null;

  function runLoop() {
      if (!running) return;

      window.sim.step(1); 
      requestAnimFrameId = requestAnimationFrame(runLoop);
  }

  // Event Handlers

  document.getElementById('drop').addEventListener('click', () => {
    window.sim.addBall(W/2, H/2 - 50, Math.random()*4 - 2, 0);
    if (!running) runLoop(); 
  });

  document.getElementById('play').addEventListener('click', () => {
      running = !running;
      if (running && requestAnimFrameId === null) runLoop();
      else if (!running) cancelAnimationFrame(requestAnimFrameId);
  });

  document.getElementById('clear').addEventListener('click', () => {
    window.sim.clear();
    running = false;
    cancelAnimationFrame(requestAnimFrameId);
  });

  canvas.addEventListener('mousedown', (e) => {
      const rect = canvas.getBoundingClientRect();

      // Calculate scale factor if CSS size != internal pixel size. 
      // Here both are ~500, so ratio is likely 1:1 or close to it.
      // Using W/H from DOM attribute as absolute resolution source for logic.
      const scaleX = (W / rect.width);
      const scaleY = (H / rect.height);

      window.sim.addBall(
          (e.clientX - rect.left) * scaleX, 
          (e.clientY - rect.top) * scaleY
      );

      if (!running) runLoop(); // If stopped by clear or init pause? Default started.
  });

})();
</script>
</body>
</html>
